#!/usr/bin/env python3
"""Turn 35 Wave 80: THE FORMATION DECISION RULES, AND A REAL CONFLICT OVER THE WIDTH SLIDER.

Wave 80's centrepieces:

1. C-030 OPENED - THE WIDTH SLIDER. The corpus carries two claims that contradict each
   other: CLAIM-0454 (C2) says a Width slider exists in tactics and changes how a formation
   plays, while CLAIM-1811 (C2, DOCUMENTED NEGATIVE) says DLS has no team-instruction system
   and lists "width or depth controls" among the things that do not exist. Wave 80 supplies a
   THIRD, independent source for the width slider (ggbro.io), which makes the negative the
   claim that has to move. The reconciliation is almost certainly a surface distinction - a
   pre-match formation width option versus an in-match team-instruction slider - but the
   negative as written is over-broad and is corrected here.

2. THE FORMATION DECISION RULES, which the corpus had as a catalogue and not as rules.
   ggbro.io supplies the operational half: pick one shape, run it for THIRTY matches (not
   five), change width before you change shape, change personnel before you change width,
   and stamina depth beats shape every time. The 4-4-2 recommendation comes with its reason -
   nothing catastrophic happens, so the shape stops being a thing you think about.

3. THE DLS26 GAMEPLAY REVIEW (r/DLS 1phcvdv, 8 Dec 2025) - a first-week account of what
   actually changed in the build: charging the keeper to cut the angle no longer works,
   whip-ins are strong, scoring is easier, and the old pass "snap" is gone so near-enough
   passes are no longer collected. Several of the corpus's device-testable gaps are
   behavioural, and this is the best written evidence on the current feel.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w80')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_fm=new_ev("ggbro.io 'The DLS 26 Formation I Actually Run, and Why Best Formation Guides Are Mostly Noise' (12 Aug 2026, a first-person account with the width finding and the evaluation rule), r/DreamLeagueSoccer 1jad1cx 'Best formation in the game?' (13 Mar 2025, the winger-as-full-wing-back requirement and the named player recommendations), r/DreamLeagueSoccer 1plnrjw 'What is the meta formation in DLS26 now?' (13 Dec 2025, the DLS26 4-4-2 with flank-running LM/RM and full-backs), r/DreamLeagueSoccer 1rx01zi 'Tips/Tricks List' (18 Mar 2026, DLS22-26, the tackle-angle rule and the shot-block stance), r/DreamLeagueSoccer 1phcvdv 'My Full DLS 26 Review After 1 Week' (8 Dec 2025, the DLS26 gameplay changes), r/DreamLeagueSoccer 176ntor 'Dream League Soccer Summed Up' (13 Oct 2023, the per-position blueprints), kostenlose-spiele-apps.de DLS26 (27 Apr 2026, the German defending doctrine), LevelWinner DLS24 beginner guide (15 Mar 2024, the slide-tackle timing rule), gamingonphone DLS26 beginner + career guides (21/27 Jan 2026, the formation unlocks and the role-assignment screen), bluestacks beginner guide (the three-kick mapping including hard kick as through ball), mokoweb.com formations guide (11 Oct 2026), ldplayer best-lineup guide (18 Apr 2025), sportsdunia DLS26 best-formations table (4 Mar 2026 - REJECTED, see the reliability register), dreamleagueforall / supercheats / dls-2017 fandom (the legacy B-vs-A defending doctrine)",
    "THE FORMATION DECISION RULES, THE WIDTH-SLIDER CONFLICT (C-030), AND THE DLS26 GAMEPLAY REVIEW. (1) THE WIDTH SLIDER - a THIRD independent source, and it makes the corpus's negative the claim that has to move: 'Width settings quietly change everything. Narrow your shape and the same eleven players play a completely different game. I ran 4-2-3-1 wide for a month, hated it, nearly abandoned the formation, then narrowed it and it clicked. Nothing about the squad or the shape had changed - I'd moved one slider. **If a shape isn't working for you, change the width before you change the shape.**' This corroborates CLAIM-0454 and contradicts CLAIM-1811's list of things that do not exist ('width or depth controls'). **C-030 is opened.** The likely reconciliation is a surface distinction - a pre-match formation width option versus an in-match team-instruction slider - but the negative as written is over-broad and is corrected to cover in-match instructions only. (2) THE EVALUATION RULE, which the corpus lacked: 'Pick one shape... Run it for **thirty matches**. Not five. Thirty. You cannot evaluate a formation across five games because the variance in this game is enormous and you'll conclude whatever the last result told you to conclude.' Plus the change-order rule: '**Change width before you change shape. Change personnel before you change width.**' (3) WHY 4-4-2 FOR A NEW PLAYER, with the reason rather than the ranking: 'Two banks of four, two up top, no clever ideas. Nothing brilliant happens. Nothing catastrophic happens either, and when you're learning, the second one matters far more than the first. You get a defensive shape that holds itself together without you thinking about it, which frees you up to learn passing weight and when to press - **the two things that actually decide games at every level of this game.**' (4) THE STAMINA CAVEAT ON THE HIGH PRESS: '4-1-2-3 with a high press. This is the shape everyone posts about. It's excellent if your squad has the stamina for it and miserable if it doesn't.' (5) THE DLS26 4-4-2 AS RUN BY A DLS26 PLAYER (Dec 2025): 'since my LM and RM are wingers, they are fast and can perform quick runs down the flanks as well as midfield duties. This is true for full-backs too. Thus, the formation can overpower the defense when attacking, as well as retreat when defending.' (6) THE WINGER-AS-FULL-WING-BACK REQUIREMENT, a concrete personnel rule: 'As long as your wingers can also perform as Full Wing Backs, meaning they have decent physical and defensive stats (tackling), or, your 2 center midfielders have very good physical stats overall. Your 2 strikers does not need to be super pacey, as long as they have decent overall and **one of them is tall**. Your center attacking midfielder can act even as a Secondary Striker or number 9.' Named options: ST Son, Salah, Mbappe, Vini, Saka, Batistuta; holding DM Rodri, Rice, Van Dijk, Petit; box-to-box Petit, Valverde, Fernandes, Odegaard, Trent, Grimaldo, Bellingham. (7) FORMATION UNLOCKS come from the Training Centre, not from play - corroborating the corpus. (8) THE ROLE-ASSIGNMENT SURFACE: clicking a player shows his attributes and the roles - captain, free kicks, penalties - are set on that screen. (9) THE TACKLE-ANGLE RULE in full: tap next to the attacker and 'if you're on the in-front of them or just off at an angle, you should generally get a good tackle in. If you are behind them at an angle, you'll likely foul them.' (10) THE DLS26 GAMEPLAY REVIEW, the best written account of the current build's feel: 'Even charging the goalie to cut off the angle does nothing now. Whip-ins are a little OP. Scoring is way too easy. Players don't snap or lock onto the ball like they used to. You have to be more precise with the pass as a pass that used to be close enough such that they would snap onto the ball no longer are collected. Defenders watch the ball go past them more. The general gameplay feels more loose.' (11) THE GERMAN DEFENDING DOCTRINE (DLS26-dated): defend patiently, no permanent pressing, **push the opponent outwards instead of engaging frontally**, use the Secondary Press deliberately. (12) THE SLIDE-TACKLE TIMING RULE: 'always from the front. Press A right on time once the ball handler is about to make contact with your defending player.' (13) The legacy B-vs-A doctrine, corroborated a third time: B (low kick when not in possession) = pressure/standing tackle, safe, rarely fouls, but once beaten you cannot recover; A = slide tackle, needs perfect timing, risks reds and penalties, but covers extra intercept distance. 'Use the B button more than the A button.' (14) A CONFLICT on which button carries the through ball: bluestacks says 'the hard kick is your primary tool for shooting and long range through balls', while the corpus's consolidated schema (CLAIM-287/0768) puts the lofted through ball on C. Recorded, not resolved. (15) sportsdunia's DLS26 formation ranking (4-4-2, 4-2-3-1, 4-2-2-2, 3-4-1-2, 4-3-3) is a THIRD rejected sportsdunia table - it is not used as evidence for the ranking.",
    "THE WIDTH SLIDER CONFLICT (C-030): a third independent source corroborates CLAIM-0454 against CLAIM-1811's negative, so the negative is narrowed to in-match team instructions only. THE FORMATION DECISION RULES: pick one shape and run it for THIRTY matches, not five; change width before you change shape; change personnel before you change width; stamina depth beats shape every time. WHY 4-4-2 FOR A NEW PLAYER: nothing catastrophic happens, so the shape stops being something you think about, which frees you to learn passing weight and when to press - the two things that decide games at every level. THE HIGH-PRESS STAMINA CAVEAT: 4-1-2-3 with a high press is excellent with stamina and miserable without it. THE WINGER-AS-FULL-WING-BACK RULE with named players, and one of two strikers must be tall. FORMATION UNLOCKS come from the Training Centre. ROLES (captain, free kicks, penalties) are set on the player screen. THE TACKLE-ANGLE RULE: in front or off at an angle wins the ball clean; behind at an angle fouls. THE DLS26 GAMEPLAY REVIEW: charging the keeper to cut the angle does nothing now, whip-ins are strong, scoring is easier, and the old pass snap is gone so near-enough passes are no longer collected. THE DEFENDING DOCTRINE: no permanent pressing, shepherd outwards rather than engaging frontally, use the Secondary Press deliberately. CONFLICT: hard kick (bluestacks) vs C button (consolidated schema) for the through ball",
    "THE FORMATION DECISION RULES, THE WIDTH-SLIDER CONFLICT, AND THE DLS26 BUILD'S FEEL",
    quality="community")

add_claim("A THIRD independent source for the width slider, and it contradicts the corpus's documented negative: 'Width settings quietly change everything. Narrow your shape and the same eleven players play a completely different game... If a shape isn't working for you, change the width before you change the shape.' **C-030 is opened against CLAIM-1811, which lists 'width or depth controls' among the things that do not exist.**", 2, "tactics/width-slider-conflict", [e_fm], notes="Opens C-030; the likely reconciliation is pre-match formation width vs in-match team instructions")
add_claim("C-030 RESOLUTION (provisional): the width option belongs to the FORMATION EDITOR - a pre-match property of the shape - and is not part of an in-match team-instruction system. CLAIM-1811's negative is therefore narrowed to **in-match instructions only** (mentality, tempo, pressing intensity, marking) and must not be read as denying the formation width setting. Both claims survive; the negative was over-broad.", 3, "tactics/width-slider-reconciliation", [e_fm], notes="Device-verifiable: open the formation editor and look for a width option")
add_claim("THE FORMATION EVALUATION RULE: pick one shape and run it for **thirty matches**, not five. 'You cannot evaluate a formation across five games because the variance in this game is enormous and you'll conclude whatever the last result told you to conclude.' This is the corpus's missing methodological rule for every formation question.", 3, "tactics/thirty-match-evaluation-rule", [e_fm])
add_claim("THE CHANGE-ORDER RULE: **change width before you change shape, and change personnel before you change width.** So a formation that is not working is diagnosed in that order, and the shape is the last thing to move.", 3, "tactics/change-order-rule", [e_fm])
add_claim("WHY 4-4-2 IS THE RECOMMENDATION FOR A NEW PLAYER, with the reason rather than the ranking: 'Two banks of four, two up top, no clever ideas. Nothing brilliant happens. Nothing catastrophic happens either, and when you're learning, the second one matters far more than the first. You get a defensive shape that holds itself together without you thinking about it, which frees you up to learn passing weight and when to press - the two things that actually decide games at every level of this game.'", 3, "tactics/why-4-4-2-for-beginners", [e_fm])
add_claim("THE HIGH-PRESS STAMINA CAVEAT: '4-1-2-3 with a high press. This is the shape everyone posts about. It's excellent if your squad has the stamina for it and miserable if it doesn't, which is the part the videos skip.' A second source for stamina depth beating shape.", 3, "tactics/high-press-stamina-caveat", [e_fm])
add_claim("THE DLS26 4-4-2 AS ACTUALLY RUN (Dec 2025): 'since my LM and RM are wingers, they are fast and can perform quick runs down the flanks as well as midfield duties. This is true for full-backs too. Thus, the formation can overpower the defense when attacking, as well as retreat when defending.' So the wide midfielders are dual-role, not pure flank players.", 3, "tactics/dls26-4-4-2-dual-role-wide-mids", [e_fm])
add_claim("THE WINGER-AS-FULL-WING-BACK REQUIREMENT, a concrete personnel rule: the wide players must have 'decent physical and defensive stats (tackling)', OR the two central midfielders must have 'very good physical stats overall'. The two strikers 'do not need to be super pacey, as long as they have decent overall and one of them is tall', and 'your center attacking midfielder can act even as a Secondary Striker or number 9.'", 3, "tactics/winger-as-full-wing-back", [e_fm])
add_claim("Named player recommendations by role, from a community formation thread: ST - Son, Salah, Mbappe, Vini, Saka, Batistuta; holding DM (strong, tall, physical) - Rodri, Rice, Van Dijk, Petit; box-to-box (fast, mobile) - Petit, Valverde, Fernandes, Odegaard, Trent, Grimaldo, Bellingham.", 3, "tactics/named-player-recommendations", [e_fm])
add_claim("Formation unlocks come from upgrading the Training Centre, not from play time - a second source, which ties the tactical surface back to the facility ladder.", 3, "tactics/formation-unlocks-from-training-centre", [e_fm])
add_claim("The role-assignment surface: clicking a player shows his attributes and the roles - captain, free kicks and penalties - are set on that same screen. A player is measured by eight attributes and his best position is read from them.", 3, "ui/role-assignment-screen", [e_fm])
add_claim("THE TACKLE-ANGLE RULE in full: tap next to the attacker, and 'if you're on the in-front of them or just off at an angle, you should generally get a good tackle in. If you are behind them at an angle, you'll likely foul them.' So the standing tackle is angle-dependent, and approaching from behind is the fouling case.", 3, "gameplay/tackle-angle-rule", [e_fm])
add_claim("THE DLS26 GAMEPLAY REVIEW (first week, 8 Dec 2025), the best written account of the current build's feel: 'Even charging the goalie to cut off the angle does nothing now. Whip-ins are a little OP. Scoring is way too easy. Players don't snap or lock onto the ball like they used to. You have to be more precise with the pass as a pass that used to be close enough such that they would snap onto the ball no longer are collected. Defenders watch the ball go past them more. The general gameplay feels more loose.'", 3, "gameplay/dls26-feel-review", [e_fm], notes="Bears on three device-testable gaps: keeper charge, pass reliability, defender behaviour")
add_claim("THE DEFENDING DOCTRINE, from a DLS26-dated source: defend patiently, **do not press permanently**, **push the opponent outwards instead of engaging frontally**, and use the Secondary Press deliberately rather than constantly. 'Patience = fewer goals conceded.'", 3, "gameplay/defending-doctrine-shepherd-outwards", [e_fm])
add_claim("THE SLIDE-TACKLE TIMING RULE: 'The correct way to use it is always from the front. Press A right on time once the ball handler is about to make contact with your defending player.' So the slide is timed to the attacker's touch, not to your approach.", 3, "gameplay/slide-tackle-timing", [e_fm])
add_claim("CONFLICT on which button carries the through ball: bluestacks states 'the hard kick is your primary tool for shooting and long range through balls', while the corpus's consolidated touch schema (CLAIM-287, CLAIM-0768) puts the lofted through ball on C. Recorded, not resolved - the corpus's schema is two-source and bluestacks is one, so the schema stands.", 3, "controls/through-ball-button-conflict", [e_fm])
add_claim("sportsdunia's DLS26 'best formations' table (4-4-2, 4-2-3-1, 4-2-2-2, 3-4-1-2, 4-3-3) is a THIRD rejected sportsdunia table. It is recorded only so the ranking is not mistaken for evidence; the corpus's formation ranking rests on other sources.", 4, "errata/sportsdunia-formation-table-rejected", [e_fm], notes="Third sportsdunia rejection")

for p in ['EV-493_formation_rules_and_width_conflict.html','EV-493b_dls26_gameplay_review.html','EV-493c_defending_doctrine.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
